CREATE TABLE IF NOT EXISTS labels (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, color TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sub_statuses (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, notes TEXT, allow_withdrawal INTEGER NOT NULL DEFAULT 1, allow_rejection INTEGER NOT NULL DEFAULT 1, allow_denial INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_labels (ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, label_id TEXT NOT NULL REFERENCES labels(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(ticket_id,label_id));
ALTER TABLE tickets ADD COLUMN sub_status_id TEXT REFERENCES sub_statuses(id) ON DELETE SET NULL;
ALTER TABLE ticket_steps ADD COLUMN author_id TEXT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE ticket_steps ADD COLUMN instruction TEXT;
